def clean(df):
    df = df.copy()
    for col in ['Category', 'Region', 'Product', 'Date']:
        if col in df.columns:
            df[col] = df[col].astype(str).str.strip()
    if 'Price' in df.columns:
        df['Price'] = pd.to_numeric(
            df['Price'].astype(str).str.replace('$', '', regex=False).str.replace(',', '', regex=False),
            errors='coerce'
        )
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
        df.loc[df['Quantity'] < 1, 'Quantity'] = df.loc[df['Quantity'] < 1, 'Quantity'].abs()
    if 'Revenue' in df.columns and 'Quantity' in df.columns and 'Price' in df.columns:
        df['Revenue'] = df['Quantity'] * df['Price']
    df = df.drop_duplicates()
    return df

def answer(df):
    d = clean(df)
    counts = d.groupby('Category')['Order_ID'].nunique()
    return {str(k): int(v) for k, v in counts.items() if pd.notna(k)}
